import{L as e,b as t,x as n}from"./vue-Vea_iehr.js";import{oi as r}from"./common-BpDe505I.js";var i=JSON.parse(`{"path":"/vm/esxi/8cbl2iji/","title":"ESXi 磁盘报错托管 I/O 故障 | ESXi","lang":"zh-CN","frontmatter":{"title":"ESXi 磁盘报错托管 I/O 故障","createTime":"2026/08/26 20:34:46","permalink":"/vm/esxi/8cbl2iji/"},"readingTime":{"minutes":1.38,"words":413},"git":{},"filePathRelative":"vm/esxi/004.esxi-disk-io-error.md","headers":[]}`),a={name:`004.esxi-disk-io-error.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h2 id="概述" tabindex="-1"><a class="header-anchor" href="#概述"><span>概述</span></a></h2><p>ESXi 开启虚拟机时若报「对象类型需要托管的 I/O」（英文：<code>Object type requires hosted I/O</code>），并伴随「模块 Disk 打开电源失败」，通常是 VMDK（Virtual Machine Disk，虚拟磁盘）的元数据或快照链损坏所致，常见于异常断电后未落盘。本文记录检查、修复磁盘，以及通过 <code>writeThrough</code> 配置根治断电丢盘的完整步骤。</p><h2 id="一、错误现象" tabindex="-1"><a class="header-anchor" href="#一、错误现象"><span>一、错误现象</span></a></h2><p><strong>Power On VM 错误日志</strong></p><table><thead><tr><th style="text-align:left;">属性</th><th style="text-align:left;">内容</th></tr></thead><tbody><tr><td style="text-align:left;">任务名称</td><td style="text-align:left;">Power On VM</td></tr><tr><td style="text-align:left;">键 (Key)</td><td style="text-align:left;"><code>haTask-50-vim.VirtualMachine.powerOn-4</code></td></tr><tr><td style="text-align:left;">描述</td><td style="text-align:left;">打开该虚拟机电源</td></tr><tr><td style="text-align:left;">虚拟机</td><td style="text-align:left;"><code>RouterOS</code></td></tr><tr><td style="text-align:left;">状况</td><td style="text-align:left;">失败 - 对象类型需要托管的 I/O</td></tr></tbody></table><p><strong>错误详情</strong></p><ul><li>对象类型需要托管的 I/O</li><li>无法打开磁盘 <code>/vmfs/volumes/6637ead3-df4cbb61-6bf3-60beb41608dc/RouterOS/chr-7.21.5.vmdk</code> 或其所依赖的快照磁盘之一。</li><li>模块「Disk」打开电源失败。</li><li>无法启动虚拟机。</li></ul><h2 id="二、检查与修复磁盘" tabindex="-1"><a class="header-anchor" href="#二、检查与修复磁盘"><span>二、检查与修复磁盘</span></a></h2><p>在 ESXi SSH 中先检查磁盘一致性：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vmkfstools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /vmfs/volumes/6637ead3-df4cbb61-6bf3-60beb41608dc/RouterOS/chr-7.21.5.vmdk</span></span></code></pre></div><p>若检查发现损坏，执行修复：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vmkfstools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repair</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /vmfs/volumes/6637ead3-df4cbb61-6bf3-60beb41608dc/RouterOS/chr-7.21.5.vmdk</span></span></code></pre></div><h2 id="三、根治断电丢盘" tabindex="-1"><a class="header-anchor" href="#三、根治断电丢盘"><span>三、根治断电丢盘</span></a></h2><p>确认磁盘正常后，关闭虚拟机，在 ESXi SSH 中向该 VM 的 <code>.vmx</code> 文件追加一行：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;disk.writeThrough = &quot;TRUE&quot;&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /vmfs/volumes/6637ead3-df4cbb61-6bf3-60beb41608dc/RouterOS/RouterOS.vmx</span></span></code></pre></div><div class="hint-container note"><p class="hint-container-title">笔记</p><p><code>.vmx</code> 与 <code>.vmdk</code> 同目录，文件名以实际 VM 目录为准（上例为 <code>RouterOS.vmx</code>）。</p></div><div class="hint-container important"><p class="hint-container-title">重要</p><p>这一行才是治断电的根：开启 <code>writeThrough</code> 后所有写直接落盘、不进 host 写缓存，断电零丢失。IDE + writeThrough 的效果与 SCSI 一致，控制器换不换其实无所谓。之后若再遇断电，开机跑 <code>vmkfstools -x check</code> 验证即可。</p></div>`,17)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};